from typing import List

class Solution:
    def mergeTriplets(self, triplets: List[List[int]], target: List[int]) -> bool:
        hit = [False] * 3
        for t in triplets:
            if any(t[i] > target[i] for i in range(3)):
                continue
            for i in range(3):
                if t[i] == target[i]:
                    hit[i] = True
        return all(hit)
