from typing import List

class Solution:
    def insert(self, intervals: List[List[int]], newInterval: List[int]) -> List[List[int]]:
        res = []
        i, n = 0, len(intervals)
        while i < n and intervals[i][1] < newInterval[0]:
            res.append(intervals[i])
            i += 1
        lo, hi = newInterval
        while i < n and intervals[i][0] <= hi:
            lo = min(lo, intervals[i][0])
            hi = max(hi, intervals[i][1])
            i += 1
        res.append([lo, hi])
        res.extend(intervals[i:])
        return res
```

**Time/Space:** O(n) / O(n)

**Pitfall:** Touching endpoints ([1,2] and [2,3]) count as overlapping here.

**Pattern:** Sort by start, then sweep

**Key insight:** After sorting, an interval overlaps the last merged one iff its start ≤ that end.

**Java**

```java
class Solution {
    public int[][] merge(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> res = new ArrayList<>();
        for (int[] iv : intervals) {
            if (!res.isEmpty() && iv[0] <= res.get(res.size() - 1)[1])
                res.get(res.size() - 1)[1] = Math.max(res.get(res.size() - 1)[1], iv[1]);
            else res.add(new int[]{iv[0], iv[1]});
        }
        return res.toArray(new int[0][]);
    }
}
```

